// MinimockUnlockUserInspect logs each unmet expectation
func (m *AdminUserUseCaseMock) MinimockUnlockUserInspect() {
	for _, e := range m.UnlockUserMock.expectations {
		if mm_atomic.LoadUint64(&e.Counter) < 1 {
			m.t.Errorf("Expected call to AdminUserUseCaseMock.UnlockUser at\n%s with params: %#v", e.expectationOrigins.origin, *e.params)
		}
	}

	afterUnlockUserCounter := mm_atomic.LoadUint64(&m.afterUnlockUserCounter)
	// if default expectation was set then invocations count should be greater than zero
	if m.UnlockUserMock.defaultExpectation != nil && afterUnlockUserCounter < 1 {
		if m.UnlockUserMock.defaultExpectation.params == nil {
			m.t.Errorf("Expected call to AdminUserUseCaseMock.UnlockUser at\n%s", m.UnlockUserMock.defaultExpectation.returnOrigin)
		} else {
			m.t.Errorf("Expected call to AdminUserUseCaseMock.UnlockUser at\n%s with params: %#v", m.UnlockUserMock.defaultExpectation.expectationOrigins.origin, *m.UnlockUserMock.defaultExpectation.params)
		}
	}
	// if func was set then invocations count should be greater than zero
	if m.funcUnlockUser != nil && afterUnlockUserCounter < 1 {
		m.t.Errorf("Expected call to AdminUserUseCaseMock.UnlockUser at\n%s", m.funcUnlockUserOrigin)
	}

	if !m.UnlockUserMock.invocationsDone() && afterUnlockUserCounter > 0 {
		m.t.Errorf("Expected %d calls to AdminUserUseCaseMock.UnlockUser at\n%s but found %d calls",
			mm_atomic.LoadUint64(&m.UnlockUserMock.expectedInvocations), m.UnlockUserMock.expectedInvocationsOrigin, afterUnlockUserCounter)
	}
}

